contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function. amount is how much Ether to forward to c.go
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");
        // read owner before the call
        address owner_before = c.owner(); if (__ESBMC_reverted()) return;

        // perform the state-changing call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner after the call
        address owner_after = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant: owner must never change due to calling go
        assert(owner_after == owner_before);
    }

    // receive so this contract can hold Ether for testing
    receive() external payable {}
}

